pub fn sparkline_groups(node: &super::SparklineGroups, scope: &mut Scope) -> Element {
    let mut writer =
        officekit_markup_base::Writer::new(scope, &super::SPARKLINE_GROUPS_SHAPE, &node.unknown);
    writer.child(&node.sparkline_group);
    writer.finish()
}

